tool_input.command:
$base="C:\Users\Administrator\.dsh\profiles\web\node_modules"
Get-ChildItem $base -Directory | Where-Object {$_.Name -like 'dsh-*'} | ForEach-Object {
  $n=$_.Name
  $has = $false
  Get-ChildItem "$base\$n\lib" -File -Filter *.js -ErrorAction SilentlyContinue | ForEach-Object {
    if (Select-String -Path $_.FullName -Pattern 'final answer|closing|收尾|## 总结|systemPrompt|PLANNER_SYSTEM' -SimpleMatch -Quiet) { $has=$true }
  }
  if ($has) { Write-Output "HIT: $n" }
}

$base="C:\Users\Administrator\.dsh\profiles\web\node_modules"
Get-ChildItem $base -Directory | Where-Object {$_.Name -like 'dsh-*'} | ForEach-Object {
  $n=$_.Name
  $files = Get-ChildItem "$base\$n\lib" -File -ErrorAction SilentlyContinue
  $tot = ($files | Measure-Object Length -Sum).Sum
  $hit = $false
  $files | ForEach-Object {
    if (Select-String -Path $_.FullName -Pattern 'PLANNER_SYSTEM','closing-check','final answer','persona','systemPrompt' -SimpleMatch -Quiet) { $hit=$true }
  }
  Write-Output ("{0,-32} bytes={1,-8} hit={2}" -f $n,$tot,$hit)
}

$env:DSH_HOME
Get-ChildItem C:\Users\Administrator\.dsh\AGENTS.md | Select-Object FullName,Length
Write-Output "=== skills dirs (SKILL.md count) ==="
Get-ChildItem D:\repository\skills -Directory | ForEach-Object {
  $s = Join-Path $_.FullName 'SKILL.md'
  if (Test-Path $s) { Write-Output ("{0}" -f $_.Name) }
}

$dirs = @("C:\Users\Administrator\.dsh\store","C:\Users\Administrator\.dsh")
foreach($d in $dirs){ if(Test-Path $d){ Get-ChildItem $d -Filter AGENTS.md -Recurse -Force -ErrorAction SilentlyContinue | Select-Object FullName,Length } }
Write-Output "=== env AGENTS ==="
Get-ChildItem env: | Where-Object {$_.Name -match 'AGENTS|INSTRUCTION'}
